## cpp
```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// 计算将 a 排成 b 需要的最小代价
ll calc(const vector<ll>& a, vector<ll> b) {
    int n = a.size();
    // cnt[x] = 在 a 前缀中出现次数 - 在 b 前缀中出现次数
    unordered_map<ll,int> cnt;
    cnt.reserve(n*2);
    ll diff = 0;   // 当前有多少个值的 cnt[x] != 0
    ll keep = 0;   // 可保留元素的总和

    for (int i = 0; i < n; i++) {
        // 插入 a[i]
        {
            ll x = a[i];
            int before = cnt[x];
            if (before != 0) diff--;     // 更新前差异计数
            int after = before + 1;
            cnt[x] = after;
            if (after != 0) diff++;      // 更新后差异计数
        }
        // 删除 b[i]
        {
            ll x = b[i];
            int before = cnt[x];
            if (before != 0) diff--;
            int after = before - 1;
            cnt[x] = after;
            if (after != 0) diff++;
        }
        // 若 diff == 0，说明前缀多重集合相同
        if (diff == 0 && a[i] == b[i]) {
            keep += a[i];
        }
    }
    return keep;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<ll> a(n);
    ll sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum += a[i];
    }

    // 升序
    vector<ll> b = a;
    sort(b.begin(), b.end());
    ll keep_asc = calc(a, b);
    // 降序
    sort(b.begin(), b.end(), greater<ll>());
    ll keep_desc = calc(a, b);

    // 最小代价 = 总和 - 最大保留和
    cout << (sum - keep_asc) << " " << (sum - keep_desc) << "\n";
    return 0;
}
