# Python 实现
# 时间复杂度 O(n log n)
import sys
from collections import defaultdict

def calc(a, b):
    cnt = defaultdict(int)
    diff = 0
    keep = 0
    for x, y in zip(a, b):
        # a 前缀插入 x
        before = cnt[x]
        if before != 0: diff -= 1
        cnt[x] = before + 1
        if cnt[x] != 0: diff += 1
        # b 前缀移除 y
        before = cnt[y]
        if before != 0: diff -= 1
        cnt[y] = before - 1
        if cnt[y] != 0: diff += 1

        if diff == 0 and x == y:
            keep += x
    return keep

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))
    total = sum(a)

    b = sorted(a)
    keep_asc = calc(a, b)
    b.reverse()
    keep_desc = calc(a, b)

    print(total - keep_asc, total - keep_desc)

if __name__ == "__main__":
    main()
